// Ringkas masukan 7 hari terakhir: apa yang paling banyak diminta orang.
const seminggu = Date.now() - 7 * 24 * 3600 * 1000;
const rows = $input.all().map(i => i.json).filter(r => Date.parse(r.diterima) >= seminggu);
const hitung = (key) => Object.entries(rows.reduce((a, r) => (a[r[key] || '-'] = (a[r[key] || '-'] || 0) + 1, a), {}))
  .sort((a, b) => b[1] - a[1]);
const kategori = hitung('kategori').map(([k, n]) => `• ${k}: ${n}`).join('\n');
const layar = hitung('layar').slice(0, 5).map(([k, n]) => `• ${k}: ${n}`).join('\n');
const p1 = rows.filter(r => r.prioritas === 'P1' && r.status !== 'selesai');
const permintaan = rows.filter(r => r.kategori === 'permintaan').slice(0, 8).map(r => `• ${r.pesan.slice(0, 120)}`).join('\n');
const teks = [
  `📊 Rangkuman masukan Qur'an App — 7 hari terakhir (${rows.length} masukan)`,
  '', 'Per kategori:', kategori || '• belum ada',
  '', 'Layar paling sering disebut:', layar || '• -',
  '', `P1 belum selesai: ${p1.length}`, ...p1.slice(0, 5).map(r => `• ${r.id} ${r.pesan.slice(0, 80)}`),
  '', 'Permintaan fitur terbaru:', permintaan || '• -',
].join('\n');
return [{ json: { teks, total: rows.length } }];
